parameters.query:
-- The page state in one statement: the token for the forms and the last 50 attempts.
SELECT jsonb_build_object(
  'generated_at', now(),
  'action_token', (SELECT value FROM config WHERE key = 'dashboard_action_token'),
  'model', (SELECT value FROM config WHERE key = 'prep_model'),
  'attempts', COALESCE((
    SELECT jsonb_agg(to_jsonb(a) ORDER BY a.created_at DESC)
    FROM (SELECT * FROM prep_attempts ORDER BY created_at DESC LIMIT 50) a
  ), '[]'::jsonb)
) AS state;

