<script>const STATE = /*__STATE__*/null;</script>
<script>
(function () {
  'use strict';

  // Same rules as the dashboard: the data arrives embedded in the page, there
  // is no fetch (n8n serves webhook HTML with an opaque origin), actions are
  // plain form posts, and page state lives in the URL hash because
  // localStorage throws in a sandboxed page.
  //
  // Everything the model writes is untrusted, so text only ever goes in
  // through textContent.

  var ACTION_URL = '/webhook/creator-program/prep/action';
  var S = STATE || sample();
  var isSample = !STATE;
  var attempts = S.attempts || [];

  var dayFmt = new Intl.DateTimeFormat('es-ES', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });

  var KIND = {
    decomposition: ['Descomposición de producto', 'p-acc'],
    screening: ['Screening conductual', 'p-warn'],
    patterns: ['Escenario de fiabilidad', 'p-ok']
  };

  var SCORE_LABEL = {
    clarifying: 'Preguntas de aclaración',
    user_focus: 'Usuario antes que arquitectura',
    scope: 'Alcance del V1',
    design: 'Diseño',
    failure_handling: 'Fallos y verificación',
    communication: 'Comunicación'
  };

  // ---- helpers ---------------------------------------------------------------

  function h(tag, props) {
    var e = document.createElement(tag);
    props = props || {};
    Object.keys(props).forEach(function (k) {
      var v = props[k];
      if (v == null) return;
      if (k === 'text') e.textContent = String(v);
      else if (k === 'class') e.className = v;
      else e.setAttribute(k, String(v));
    });
    for (var i = 2; i < arguments.length; i++) {
      var c = arguments[i];
      if (c == null || c === false) continue;
      e.appendChild(typeof c === 'object' ? c : document.createTextNode(String(c)));
    }
    return e;
  }

  function list(items, cls) {
    var ul = h('ul', { class: 'plain ' + (cls || '') });
    (items || []).forEach(function (t) { ul.appendChild(h('li', { text: t })); });
    return ul;
  }

  function uuid() {
    var b = new Uint8Array(16);
    crypto.getRandomValues(b);
    b[6] = (b[6] & 15) | 64;
    b[8] = (b[8] & 63) | 128;
    var x = Array.prototype.map.call(b, function (v) { return (v + 256).toString(16).slice(1); }).join('');
    return x.slice(0, 8) + '-' + x.slice(8, 12) + '-' + x.slice(12, 16) + '-' + x.slice(16, 20) + '-' + x.slice(20);
  }

  function avgScore(a) {
    var s = a.feedback && a.feedback.scores;
    if (!s) return null;
    var keys = Object.keys(SCORE_LABEL);
    return keys.reduce(function (t, k) { return t + Number(s[k] || 0); }, 0) / keys.length;
  }

  // ---- hash state ---------------------------------------------------------------

  function readHash() { return new URLSearchParams(location.hash.slice(1)); }
  var hp = readHash();
  var tab = hp.get('t') || (hp.get('a') || hp.get('f') ? 'sim' : 'process');
  var selected = hp.get('a') || (attempts[0] && attempts[0].id) || '';
  var flashKey = hp.get('f');

  function writeHash() {
    var p = new URLSearchParams();
    p.set('t', tab);
    if (selected) p.set('a', selected);
    history.replaceState(null, '', '#' + p.toString());
  }

  // ---- forms --------------------------------------------------------------------
  // Each form carries the token only this rendered page knows. Waiting for
  // Claude takes a while, so the button says so and cannot be pressed twice.

  function actionForm(fields, label, cls, busy) {
    var f = h('form', { method: 'post', action: ACTION_URL });
    fields.token = S.action_token || '';
    Object.keys(fields).forEach(function (k) {
      f.appendChild(h('input', { type: 'hidden', name: k, value: fields[k] }));
    });
    var b = h('button', { type: 'submit', class: 'btn ' + (cls || ''), text: label });
    if (isSample) { b.disabled = true; b.title = 'No disponible en la vista previa'; }
    f.addEventListener('submit', function () {
      Array.prototype.forEach.call(document.querySelectorAll('button[type=submit]'), function (x) { x.disabled = true; });
      b.textContent = busy || 'Claude está pensando…';
    });
    return { form: f, button: b };
  }

  // ---- 1. the process -----------------------------------------------------------

  function viewProcess() {
    var stages = [
      ['01', 'Screening', 'Primero con un agente de voz de ElevenLabs y después 30 minutos con recruiter: trayectoria, interés por el audio con IA y capacidad de trabajar con autonomía en remoto.'],
      ['02', 'Prueba de código', 'Asíncrona, de 60 a 90 minutos en CoderPad, con dos problemas de dificultad media tipo LeetCode.'],
      ['03', 'Coding práctico', 'En vivo. No solo algoritmos: depurar o extender código real, explicando mientras lo haces.'],
      ['04', 'Descomposición de producto', 'Un flujo manual y desordenado (piensa en una hoja de cálculo de doblaje) que diseñas de extremo a extremo: UI, API y backend. Mitad ingeniería, mitad producto.']
    ];
    var grid = h('div', { class: 'grid2' });
    stages.forEach(function (s) {
      grid.appendChild(h('div', { class: 'card stage' },
        h('div', { class: 'n', text: s[0] }), h('h3', { text: s[1] }), h('p', { text: s[2] })));
    });

    return h('div', {},
      h('div', { class: 'section-head' }, h('h2', { text: 'El proceso' }),
        h('p', { text: 'Suele durar de 3 a 4 semanas. Automation Engineer está entre los roles con entrevista más exigente de la empresa.' })),
      grid,
      h('div', { class: 'grid2', style: 'margin-top:14px' },
        h('div', { class: 'card' },
          h('h3', { text: 'Lo que valoran' }),
          list([
            'Simplicidad frente a over engineering: la solución más pequeña que resuelve el problema.',
            'Ownership: no hay product managers, el ingeniero decide y responde del resultado.',
            'Pensar en el usuario final antes que en la arquitectura.',
            'Contar el razonamiento en voz alta y preguntar pronto.',
            'Proyectos propios construidos y lanzados, no solo tareas asignadas.',
            'Entusiasmo real por lo que construyen en voz e IA.'
          ], 'list-ok')),
        h('div', { class: 'card' },
          h('h3', { text: 'Tus huecos a trabajar' }),
          list([
            'Fiabilidad específica de LLMs: un modelo falla devolviendo algo plausible y equivocado, no con un 503.',
            'Empezar por el usuario y la UI, no por la cola. Tu instinto natural es empezar por la cola.',
            'Estructura al hablar: buenas decisiones que el entrevistador no puede seguir no puntúan.'
          ], 'list-warn'),
          h('p', { class: 'hint', style: 'margin-top:10px', text: 'Tu mejor material: este mismo repo. Idempotencia por clave natural, reintentos que distinguen transitorio de permanente, DLQ con replay y observabilidad en tres capas.' })))
    );
  }

  // ---- 2. patterns --------------------------------------------------------------

  var PATTERNS = [
    { t: 'Idempotencia', s: 'reintentar no duplica efectos',
      what: 'Ejecutar la misma operación dos veces deja el sistema igual que ejecutarla una.',
      why: 'Todo lo que reintenta (colas, webhooks, n8n, un operador nervioso) acaba ejecutando algo dos veces. Sin idempotencia eso son dos emails, dos cobros o dos filas.',
      ex: 'Clave estable derivada de la entrada (event_id, order_id) guardada con una restricción UNIQUE. La primera vez se procesa; la segunda, INSERT ... ON CONFLICT DO NOTHING. Hacia fuera, se manda una idempotency key al proveedor.',
      verify: ['Test que ejecuta el mismo paso dos veces y comprueba que hay una sola fila y un solo envío.', 'Consulta periódica de duplicados por clave natural: debe devolver cero.'],
      repo: 'UNIQUE(external_id) con INSERT OR IGNORE en screen, y el código de seguimiento como sha1 del id de la solicitud: sale igual en cada reintento.' },
    { t: 'Reintentos con backoff y jitter', s: 'solo lo transitorio se reintenta',
      what: 'Reintentar tras esperas crecientes (1 s, 2 s, 4 s...) con una parte aleatoria, y con un tope de intentos.',
      why: 'Un 503 o un timeout suelen resolverse solos. Un 400 no: reintentarlo desperdicia intentos y retrasa la alerta. Sin jitter, todo lo que falló a la vez reintenta a la vez y vuelve a tumbar al proveedor.',
      ex: 'Clasificar el error: timeout, 429 y 5xx son transitorios; validación y 404 son permanentes y van directos a la DLQ. Guardar attempts y next_attempt_at en la tarea para que la espera sobreviva a un reinicio.',
      verify: ['Proveedor falso que falla un porcentaje de llamadas a propósito.', 'Test que comprueba que un error permanente no se reintenta nunca.'],
      repo: 'TransientError y PermanentError en retry.py, y la clasificación en un único sitio, runner.py. PLATFORM_FAILURE_RATE=0.25 hace que el camino de reintentos se ejecute en cada demo.' },
    { t: 'Dead letter queue', s: 'un fallo que se puede reprocesar',
      what: 'Donde va lo que agotó sus intentos o no puede procesarse, con todo lo necesario para volver a lanzarlo.',
      why: 'Sin ella los fallos desaparecen en logs que nadie lee. Si reprocesar exige editar la base de datos a mano, la automatización es trabajo manual disfrazado.',
      ex: 'Tabla con payload, error, motivo (invalid, exhausted, crashed), enlace a la ejecución y replayed_at. Un comando o botón para relanzar, que se niega a relanzar dos veces.',
      verify: ['Alerta cuando crece la DLQ, no por cada fila.', 'Métrica de antigüedad del elemento más viejo sin resolver.'],
      repo: 'dead_letters con replay, y en n8n el índice único que evita que un registro roto se convierta en 32 filas en una semana.' },
    { t: 'Orquestación y coreografía', s: 'quién sabe el orden de los pasos',
      what: 'Orquestación: un coordinador central llama a cada paso en orden. Coreografía: cada paso emite un evento y otros reaccionan.',
