const recent = row.recent_titles ?? [];

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const KINDS = ['decomposition', 'screening', 'patterns'];
const MAX_TEXT = 20000;

const action = String(body.action ?? '');
const id = UUID.test(String(body.id ?? '')) ? String(body.id) : '';
const kind = String(body.kind ?? '');
const text = String(body.text ?? '').trim();

function skip(flash) {
  return [{ json: { skip: true, flash, id } }];
}

if (!id) return skip('invalid');
if (text.length > MAX_TEXT) return skip('too_long');

const SYSTEM = [
  'Eres un entrevistador técnico de ElevenLabs para el puesto de Automation Engineer.',
  'ElevenLabs es una empresa de IA de voz y audio sin capas de product management: los ingenieros son dueños del producto de principio a fin.',
  'El proceso incluye un screening, una prueba de código, coding en vivo y una ronda de descomposición de producto, donde el candidato recibe un flujo manual y desordenado y lo diseña de extremo a extremo: UI, API y backend.',
  'Se valora la simplicidad frente al over engineering, el ownership, pensar en el usuario final antes que en la arquitectura, comunicar el razonamiento en voz alta y haber construido y lanzado proyectos propios.',
  'El candidato trabaja sobre todo con n8n, scripts propios e integraciones con LLMs.',
  'Escribe siempre en español. No uses guiones ni rayas en ningún texto.',
].join(' ');

const KIND_BRIEF = {
  decomposition:
    'Ronda de descomposición de producto. Un proceso manual y desordenado, verosímil y concreto ' +
    '(una hoja de cálculo compartida, aprobaciones por email, tareas repetitivas entre equipos), ' +
    'preferiblemente de una empresa de voz, audio, doblaje, contenido o de las operaciones internas de una empresa de IA. ' +
    'El candidato tendrá que diseñar usuarios, alcance del V1, UI, modelo de datos, API, automatización, fallos y cómo sabe que funciona.',
  screening:
    'Screening conductual. context describe quién entrevista y en qué momento del proceso. ' +
    'client_ask son exactamente 3 preguntas numeradas que haría esa persona: por ejemplo un pitch de 2 minutos, ' +
    'por qué ElevenLabs, por qué automatización, un proyecto propio lanzado, un fallo en producción del que fue responsable, ' +
    'una decisión de simplificar. Varía las preguntas entre casos.',
  patterns:
    'Escenario de fiabilidad. Una automatización concreta que falla de una forma realista: duplicados al reintentar, ' +
    'un paso de cinco que falla a medias, un LLM que devuelve algo plausible pero equivocado, un proveedor caído, ' +
    'alertas tan ruidosas que se ignoran, datos de entrada corruptos. El candidato debe explicar qué está pasando, ' +
    'qué patrón lo resuelve y cómo verificaría que la solución funciona.',
};

const CASE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['title', 'context', 'client_ask', 'hidden_facts', 'evaluation'],
  properties: {
    title: { type: 'string' },
    context: { type: 'string' },
    client_ask: { type: 'string' },
    hidden_facts: { type: 'array', items: { type: 'string' } },
    evaluation: { type: 'array', items: { type: 'string' } },
  },
};

const REPLY_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['reply'],
  properties: { reply: { type: 'string' } },
};

const SCORE_KEYS = ['clarifying', 'user_focus', 'scope', 'design', 'failure_handling', 'communication'];

const FEEDBACK_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['verdict', 'scores', 'strengths', 'missing', 'overengineered',
             'interviewer_questions', 'model_answer', 'next_step'],
  properties: {
    verdict: { type: 'string' },
    scores: {
      type: 'object',
      additionalProperties: false,
      required: SCORE_KEYS,
      properties: Object.fromEntries(SCORE_KEYS.map((k) => [k, { type: 'integer' }])),
    },
    strengths: { type: 'array', items: { type: 'string' } },
    missing: { type: 'array', items: { type: 'string' } },
    overengineered: { type: 'array', items: { type: 'string' } },
    interviewer_questions: { type: 'array', items: { type: 'string' } },
    model_answer: { type: 'array', items: { type: 'string' } },
    next_step: { type: 'string' },
  },
};

function request(effort, system, user, schema) {
  return {
    model: String(cfg.prep_model || 'claude-opus-5'),
    max_tokens: 16000,
    // Server-side refusal fallback; needs the anthropic-beta header set on Ask Claude.
    fallbacks: 'default',
    output_config: { effort, format: { type: 'json_schema', schema } },
    system,
    messages: [{ role: 'user', content: user }],
  };
}

function caseText(a) {
  return JSON.stringify({ kind: a.kind, title: a.title, ...a.brief }, null, 2);
}

function transcriptText(t) {
  if (!t.length) return '(ninguna)';
  return t.map((x, i) => `${i + 1}. Candidato: ${x.q}\n   Cliente: ${x.a}`).join('\n');
}

function go(req) {
  return [{ json: { skip: false, flash: action, id, action, kind, text, attempt, request: req } }];
}

if (action === 'case') {
  if (attempt) return skip('case');
  if (!KINDS.includes(kind)) return skip('invalid');
  const avoid = recent.length ? recent.map((t) => `"${t}"`).join(', ') : '(ninguno)';
  return go(request('medium', SYSTEM,
    `Escribe un caso nuevo para practicar.\n\nTipo: ${KIND_BRIEF[kind]}\n\n` +
    `No repitas ni se parezca a estos títulos ya usados: ${avoid}.\n\n` +
    'Campos:\n' +
    'title: corto y concreto.\n' +
    'context: la situación en 2 a 4 frases.\n' +
    'client_ask: lo que pide el cliente o el entrevistador, con su propia voz.\n' +
    'hidden_facts: 6 a 10 datos que el candidato solo conocerá si pregunta (volumen, usuarios y roles, ' +
    'herramientas actuales, restricciones, plazos, qué pasa hoy cuando algo falla).\n' +
    'evaluation: 5 a 7 criterios concretos con los que un entrevistador de ElevenLabs evaluaría la respuesta a este caso.',
    CASE_SCHEMA));
}

if (action === 'ask') {
  if (!attempt || attempt.feedback || !text) return skip('invalid');
  const transcript = attempt.transcript ?? [];
  // The page sends how many questions it had already seen. Anything else is a resubmit.
  if (Number(body.turn) !== transcript.length) return skip('ask');
  return go(request('low',
    SYSTEM + ' En esta conversación haces de cliente del caso, no de entrevistador.',
    `El caso:\n${caseText(attempt)}\n\nPreguntas anteriores:\n${transcriptText(transcript)}\n\n` +
    `Nueva pregunta del candidato: ${text}\n\n` +
    'Responde como el cliente, en 1 a 4 frases, usando hidden_facts y lo que ese cliente sabría de forma razonable. ' +
    'Si el cliente no lo sabría, dilo. No des pistas de diseño, no evalúes la pregunta y no reveles criterios de evaluación.',
    REPLY_SCHEMA));
}

if (action === 'answer') {
  if (!attempt || !text) return skip('invalid');
  if (attempt.feedback) return skip('answer');
  return go(request('high', SYSTEM,
    `El caso:\n${caseText(attempt)}\n\nPreguntas de aclaración que hizo el candidato antes de responder:\n` +
    `${transcriptText(attempt.transcript ?? [])}\n\nRespuesta del candidato:\n${text}\n\n` +
    'Evalúa como un entrevistador exigente de ElevenLabs. Sé directo: si algo falta o sobra, dilo y explica por qué, sin suavizar. ' +
    'Usa los criterios de evaluation. En descomposición, no haber preguntado nada es una carencia seria. ' +
    'Valora la simplicidad, pensar en el usuario antes que en la arquitectura y que el razonamiento se pueda seguir en voz alta.\n\n' +
    'Campos:\n' +
    'verdict: 2 o 3 frases con la conclusión, como la escribiría el entrevistador en su informe.\n' +
    'scores: de 1 a 5 cada uno. clarifying (preguntas de aclaración), user_focus (usuario antes que arquitectura), ' +
    'scope (V1 pequeño y lanzable), design (UI, datos y API coherentes; en screening, sustancia técnica de los ejemplos), ' +
    'failure_handling (fallos, reintentos, verificación), communication (estructura y claridad).\n' +
    'strengths: lo que hizo bien, concreto.\n' +
    'missing: lo que faltó y por qué importa.\n' +
    'overengineered: dónde diseñó de más; vacío si no pasó.\n' +
    'interviewer_questions: 3 a 5 preguntas de seguimiento que haría el entrevistador ahora.\n' +
    'model_answer: 5 a 8 puntos clave de una respuesta fuerte a este caso.\n' +
    'next_step: una sola cosa concreta que practicar en el siguiente caso.',
    FEEDBACK_SCHEMA));
}

return skip('invalid');

// Treat Claude's reply like any other external input: nothing reaches the
// table unless it has the shape the page expects.
//
// Structured outputs guarantee valid JSON, not useful JSON. A refusal or a
// reply cut off at max_tokens does not match the schema at all, and an empty
// title or a score of 9 would match it and still break the page.

const plan = $('Plan the call').first().json;
const res = $json;

function fail(flash) {
  return [{ json: { ok: false, flash, id: plan.id } }];
}

if (res.stop_reason === 'refusal') return fail('refused');
if (res.stop_reason !== 'end_turn') return fail('bad_reply');

const block = (res.content ?? []).find((b) => b.type === 'text');
let out;
try {
  out = JSON.parse(block?.text ?? '');
} catch (e) {
  return fail('bad_reply');
}

const str = (v) => typeof v === 'string' && v.trim().length > 0;
const strs = (v, min) => Array.isArray(v) && v.length >= min && v.every(str);
const model = String(res.model ?? '');

let row;

if (plan.action === 'case') {
  if (!str(out.title) || !str(out.context) || !str(out.client_ask) ||
      !strs(out.hidden_facts, 3) || !strs(out.evaluation, 3)) return fail('bad_reply');
  row = {
    id: plan.id, kind: plan.kind, title: out.title.trim(), model,
    brief: { context: out.context, client_ask: out.client_ask,
             hidden_facts: out.hidden_facts, evaluation: out.evaluation },
    transcript: [], answer: null, feedback: null,
  };
} else if (plan.action === 'ask') {
  if (!str(out.reply)) return fail('bad_reply');
  const a = plan.attempt;
  row = { ...a, transcript: [...(a.transcript ?? []), { q: plan.text, a: out.reply.trim() }] };
} else if (plan.action === 'answer') {
  const keys = ['clarifying', 'user_focus', 'scope', 'design', 'failure_handling', 'communication'];
  const s = out.scores ?? {};
  const scoresOk = keys.every((k) => Number.isInteger(s[k]) && s[k] >= 1 && s[k] <= 5);
  if (!scoresOk || !str(out.verdict) || !str(out.next_step) || !strs(out.strengths, 1) ||
      !strs(out.missing, 0) || !strs(out.overengineered, 0) ||
      !strs(out.interviewer_questions, 1) || !strs(out.model_answer, 1)) return fail('bad_reply');
  row = { ...plan.attempt, answer: plan.text, feedback: { ...out, model } };
} else {
  return fail('invalid');
}

return [{ json: { ok: true, flash: plan.action, id: plan.id, row } }];
